import {BUILDINGS} from './catalog.js';
export const OWN_BUILDINGS={hq:0,house:1,goldmine:2,lumber:3,supply:4,metal:5,storage:6,infantry:7,range:7,vehicle:8,builders:8,air:9,heliport:9,stealth:9,research:10,robotics:10,fusion:10,tower:11,cannon:12,wall:13,hospital:14,embassy:15,market:15,bunker:12,fortress:0,shipyard:6};
export function ownFamily(type){const b=BUILDINGS[type];if(!b)return null;if(Object.hasOwn(OWN_BUILDINGS,type))return OWN_BUILDINGS[type];if(b.resource)return({gold:2,wood:3,supply:4,metal:5})[b.resource];return({command:0,economy:1,production:5,military:7,science:10,defense:b.size===1?11:12,support:15,infrastructure:6,decoration:15,scenario:6})[b.kind]??(b.attack?12:10);}
let metadata,sheet;const thumbs=new Map(),variants=new Map();
export const ownArtReady=typeof document==='undefined'?Promise.resolve():Promise.all([fetch(new URL('./auralis/buildings.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Catálogo Auralis no disponible');return r.json();}),new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=new URL('./auralis/buildings.png',import.meta.url).href;})]).then(([data,image])=>{metadata=data;sheet=image;});
export function ownAsset(type,level=1){const family=ownFamily(type);if(family===null||!metadata)return null;const frame=metadata.frames[family],key=family+':'+level;if(!variants.has(key))variants.set(key,{file:new URL('./auralis/buildings.png',import.meta.url).href,frames:[frame],states:{idle:[[0]]},displayWidth:frame[2],own:true,family,level});return variants.get(key);}
export function ownThumbnail(type,level=1){const a=ownAsset(type,level);if(!a||!sheet)return'';const key=a.family+':'+level;if(thumbs.has(key))return thumbs.get(key);const c=document.createElement('canvas');c.width=180;c.height=170;const x=c.getContext('2d'),f=a.frames[0],scale=Math.min(166/f[2],151/f[3]);x.drawImage(sheet,...f,(180-f[2]*scale)/2,158-f[3]*scale,f[2]*scale,f[3]*scale);if(level>1){x.fillStyle='#234655';x.fillRect(58,155,64,12);x.fillStyle='#e8c476';x.fillRect(60,157,60*Math.min(10,level)/10,8);}const url=c.toDataURL('image/png');thumbs.set(key,url);return url;}
export const ownSheet=()=>sheet;
